def bfs_4_val(start_cells, val):
    """BFS starting from seed cells, following cells with 'val'"""
    visited = set(start_cells)
    queue = list(start_cells)

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
